<?php
class Kategori { private $db; public function __construct(PDO $db) { $this->db = $db; } public function all():array{return $this->db->query('SELECT k.*,COUNT(a.id) jumlah_alat FROM kategori k LEFT JOIN alat a ON a.kategori_id=k.id GROUP BY k.id ORDER BY k.id DESC')->fetchAll();} public function find(int $id){$s=$this->db->prepare('SELECT * FROM kategori WHERE id=?');$s->execute([$id]);return $s->fetch()?:null;} public function create($n,$d):int{$s=$this->db->prepare('INSERT INTO kategori(nama_kategori,deskripsi) VALUES(?,?)');$s->execute([$n,$d]);return(int)$this->db->lastInsertId();} public function update(int $id,$n,$d){$s=$this->db->prepare('UPDATE kategori SET nama_kategori=?,deskripsi=? WHERE id=?');$s->execute([$n,$d,$id]);} public function delete(int $id){$s=$this->db->prepare('DELETE FROM kategori WHERE id=?');$s->execute([$id]);} }
